bisect_inverse <- function(F, u, itv = c(0, 1), delta = 1e-8, N = 1000) {
  # 檢查 u
  if (u <= 0 || u >= 1) {
    stop("u must be strictly between 0 and 1.")
  }
  # 定義目標函數 g(x) = F(x) - u
  g <- function(x) F(x) - u

  a <- itv[1]; b <- itv[2]
  fa <- g(a); fb <- g(b)

  # 檢查根是否被括住
  if (fa * fb > 0) {
    stop("g(a) and g(b) must have opposite signs. The root is not bracketed.")
  }

  iter <- 0; err <- Inf; pt <- NA
  while (err > delta && iter < N) {
    pt <- (a + b)/2
    val <- g(pt)
    err <- abs(val)

    if (val == 0) {
      break  # 找到精確的根
    } else if (fa * val < 0) {
      b <- pt; fb <- val
    } else {
      a <- pt; fa <- val
    }

    iter <- iter + 1
  }

  if (iter >= N) {
    warning("已達到最大迭代次數，但未完全收斂。")
  }

  return(pt)
}
